/** 참여자에게 추가 맥락을 묻는 되묻기 도메인입니다. */
package com.dandimate.durooduroo.askback.domain;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="askbacks") public class Askback { @Id private String id; @Column(nullable=false) private String roomId; @Column(nullable=false) private String targetMemberId; @Column(nullable=false) private String question; @Column(nullable=false) private String status; @Column(nullable=false) private LocalDateTime createdAt; protected Askback(){} private Askback(String r,String t,String q){id=UUID.randomUUID().toString();roomId=r;targetMemberId=t;question=q;status="PENDING";createdAt=LocalDateTime.now();} public static Askback create(String r,String t,String q){return new Askback(r,t,q);} public void answer(){status="ANSWERED";} public void forgot(){status="FORGOT";} public void postpone(){status="PENDING";} public String getId(){return id;} public String getRoomId(){return roomId;} public String getTargetMemberId(){return targetMemberId;} public String getQuestion(){return question;} public String getStatus(){return status;} public LocalDateTime getCreatedAt(){return createdAt;} }
